result = []
for k in range(goal['min_count'], goal['max_count'] + 1):
    for combo in combinations(ids, k):
        # Check requires closure if required
        if goal['closed_dependencies']:
            # Collect all requires recursively
            required_ids = set()
            stack = list(combo)
            while stack:
                current = stack.pop()
                if current not in required_ids:
                    required_ids.add(current)
                    stack.extend(opts_by_id[current]['requires'])
            if not all(r in combo for r in required_ids):
                continue
