                        conflict_found = True
                        break
                if conflict_found:
                    break
            if conflict_found:
                continue
        # Check cover tags
        cover_tags = goal['cover'].get('tags', [])
        tags_covered = set()
        for cid in combo:
            tags_covered.update(opts_by_id[cid].get('tags', []))
        if not all(tag in tags_covered for tag in cover_tags):
            continue
        # Check sum_bounds cost max
        total_cost = sum(opts_by_id[cid].get('cost', 0) for cid in combo)
        cost_max = goal['sum_bounds'].get('cost', {}).get('max', None)
        if cost_max is not None and total_cost > cost_max:
            continue
        # Check unique fields
        unique_fields = goal.get('unique', [])
        unique_ok = True
        for field in unique_fields:
            vals = [opts_by_id[cid].get(field) for cid in combo]
            if len(vals) != len(set(vals)):
                unique_ok = False
                break
        if not unique_ok:
            continue
        # Check order_by ascending lexicographic
        order_by = goal.get('order_by', [])
        if order_by:
            sorted_combo = sorted(combo, key=lambda cid: tuple(opts_by_id[cid].get(f, '') for f in order_by))
            if list(combo) != sorted_combo:
                continue
        # Check valid
        if valid(list(combo)):
            result = list(combo)
            break
    if result:
        break

